'use client'
import { Button } from '@/components/ui/Button'
import { Field } from '@/components/ui/Field'
import { Input } from '@/components/ui/Input'
import { Textarea } from '@/components/ui/Textarea'
import { FooterRow } from '@/components/site/FooterRow'
import { SiteHeader } from '@/components/site/SiteHeader'
import { contactContent, type ContactContent, contactSections, type ContactSection } from '@/lib/pages/contact'
import { cn } from '@/lib/cn'
import { pageSections } from '@/lib/image'
import { Fragment, type ReactNode } from 'react'
import type { HeaderMenus } from '@/lib/site-header'

// The contact page from library items: the heading and a line in the first column, the form on the card fill in the
// other (name, work email, message and one White button), one column on phones. The form posts to `content.form.action`
// unless `onSubmit` takes it. `content` replaces the copy (lib/pages/contact.ts).
export interface ContactPageProps {
  content?: ContactContent
  /** Receives the form's values instead of posting it. */
  onSubmit?: (values: { name: string; email: string; message: string }) => void
  /** The header menus' content, pictures included (the live card's `picture`, the use cases' `shots`); Acme by default. */
  menus?: HeaderMenus
  /** The sections to show, in order; all of them in the page order by default (leave one out to omit it). */
  sections?: readonly ContactSection[]
  className?: string
}

const WRAP = 'mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)'

export function ContactPage({ content: c = contactContent, onSubmit, menus, sections, className }: ContactPageProps) {
  const f = c.form
  const parts: Record<ContactSection, ReactNode> = {
    intro: (
      <div className="grid max-w-xl gap-6">
        <h1 className="type-section">{c.headline}</h1>
        <p className="type-body-lg text-fg-soft">{c.body}</p>
      </div>
    ),
    form: (
      <form
        aria-label={f.label}
        action={f.action}
        method="post"
        onSubmit={onSubmit ? (e) => {
          e.preventDefault()
          const d = new FormData(e.currentTarget)
          onSubmit({ name: String(d.get('name') ?? ''), email: String(d.get('email') ?? ''), message: String(d.get('message') ?? '') })
        } : undefined}
        className="grid gap-6 rounded-container bg-surface-raised p-8 max-sm:p-6"
      >
        <Field label={f.name.label}>
          {({ id }) => <Input id={id} name="name" autoComplete="name" placeholder={f.name.placeholder} required />}
        </Field>
        <Field label={f.email.label} description={f.email.description}>
          {({ id, describedBy }) => <Input id={id} name="email" type="email" autoComplete="email" placeholder={f.email.placeholder} aria-describedby={describedBy} required />}
        </Field>
        <Field label={f.message.label}>
          {({ id }) => <Textarea id={id} name="message" rows={6} placeholder={f.message.placeholder} required />}
        </Field>
        <Button type="submit" className="w-full">{f.submit}</Button>
      </form>
    ),
  }
  return (
    <div data-ds="contact-page" className={cn('flex min-h-dvh flex-col bg-surface text-fg', className)}>
      <SiteHeader menus={menus} links={c.header.nav} secondary={c.header.secondary} cta={c.header.cta} />
      <main className={cn(WRAP, 'grid flex-1 grid-cols-2 items-start gap-12 py-24 max-md:grid-cols-1 max-md:gap-8 max-sm:py-16')}>
        {pageSections(contactSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}
      </main>
      <footer className="border-t border-edge">
        <div className={cn(WRAP, 'py-10')}>
          <FooterRow domain={c.footer.domain} homeHref="/" links={c.footer.links} />
        </div>
      </footer>
    </div>
  )
}

export default ContactPage

// The contact page template's copy: short declarative sentences and a form with three fields. No address, phone
// number or reply time is stated: the brand assets give none. Both flavors read this file.
const nav = [
	{ label: 'Product', href: '/product' },
	{ label: 'Pricing', href: '/pricing' },
	{ label: 'Changelog', href: '/changelog' },
	{ label: 'Blog', href: '/blog' },
]
const footer = {
	domain: 'spyglass.so',
	links: [
		{ label: 'Product', href: '/product' },
		{ label: 'Pricing', href: '/pricing' },
		{ label: 'About', href: '/about' },
		{ label: 'Changelog', href: '/changelog' },
		{ label: 'Blog', href: '/blog' },
		{ label: 'Terms', href: '/legal' },
	],
}
const header = { nav, secondary: { label: 'Sign in', href: '/sign-in' }, cta: { label: 'Get 50% off', href: '/pricing' } }

export const contactContent = {
	header,
	headline: 'Talk to us.',
	body: 'Questions about a plan, your team or the index. Send a note and a person reads it.',
	form: {
		label: 'Contact',
		action: '/contact',
		name: { label: 'Name', placeholder: 'Alex at Acme' },
		email: { label: 'Work email', placeholder: 'you@acme.com', description: 'Where we write back.' },
		message: { label: 'Message', placeholder: 'What would you like to know?' },
		submit: 'Send message',
	},
	footer,
}

export type ContactContent = typeof contactContent

/** The contact page's sections in order; pass `sections` to reorder them or leave some out. */
export const contactSections = ['intro', 'form'] as const
export type ContactSection = (typeof contactSections)[number]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
